 void receive(String from,String packet){try{String[] p=packet.split(":",4);if(p.length!=4)return;int i=Integer.parseInt(p[1],16),n=Integer.parseInt(p[2],16);if(n<1||n>65535||i<0||i>=n)return;String key=from+":"+p[0];if(incoming.size()>16)incoming.clear();String[] parts=incoming.get(key);if(parts==null){parts=new String[n];incoming.put(key,parts);}if(parts.length!=n)return;parts[i]=p[3];for(String s:parts)if(s==null)return;String data=String.join("",parts);incoming.remove(key);if(data.length()>5000000)return;js("window.ThienMenhLink&&ThienMenhLink.message("+JSONObject.quote(from)+","+JSONObject.quote(data)+")");}catch(Exception ignored){}}
 void queue(String data){if(data.length()>5000000)return;if(hosting){for(BluetoothDevice d:peers.values())frames(d,data,limits.getOrDefault(d.getAddress(),20));}else if(client!=null&&writeChar!=null)frames(null,data,limits.getOrDefault("host",20));flush();}
 void frames(BluetoothDevice d,String data,int max){int size=Math.max(1,Math.min(140,max-17)),total=(data.length()+size-1)/size;if(total>65535){status("error","Gói Bluetooth quá lớn.");return;}int id=(++serial)&0xffffff;for(int i=0;i<total;i++)outgoing.add(new Packet(d,String.format(Locale.ROOT,"%06x:%04x:%04x:",id,i,total)+data.substring(i*size,Math.min(data.length(),(i+1)*size))));}
 void flush(){if(busy||outgoing.isEmpty())return;Packet p=outgoing.poll();busy=true;boolean ok;if(hosting){if(server==null||!peers.containsKey(p.device.getAddress())){busy=false;flush();return;}notifyChar.setValue(p.data.getBytes(StandardCharsets.UTF_8));ok=server.notifyCharacteristicChanged(p.device,notifyChar,false);}else{if(client==null||writeChar==null){outgoing.clear();busy=false;return;}writeChar.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT);writeChar.setValue(p.data.getBytes(StandardCharsets.UTF_8));ok=client.writeCharacteristic(writeChar);}if(!ok){busy=false;status("error","Kênh Bluetooth đang bận; kết nối lại nếu không đồng bộ.");}}
 void shutdown(){try{if(adapter!=null&&adapter.isEnabled()){if(scanCallback!=null)adapter.getBluetoothLeScanner().stopScan(scanCallback);if(adapter.getBluetoothLeAdvertiser()!=null)adapter.getBluetoothLeAdvertiser().stopAdvertising(advertiser);}if(client!=null){client.disconnect();client.close();}if(server!=null)server.close();}catch(Exception ignored){}client=null;server=null;peers.clear();incoming.clear();outgoing.clear();busy=false;}
